8\\u0947\\u091f\\u0964\\n   - **\\u0928\\u093f\\u092f\\u0902\\u0924\\u094d\\u0930\\u093f\\u0924 \\u0926\\u0941\\u0930\\u094d\\u0932\\u092d \\u092a\\u0948\\u091f\\u0930\\u094d\\u0928 \\u0907\\u0902\\u091c\\u0947\\u0915\\u094d\\u0936\\u0928:** \\u0915\\u0941\\u0932 \\u0921\\u0947\\u091f\\u093e \\u0915\\u093e \\u0920\\u0940\\u0915 1.5% \\u0939\\u093f\\u0938\\u094d\\u0938\\u093e 3 \\u0905\\u0932\\u0917-\\u0905\\u0932\\u0917 \\u0926\\u0941\\u0930\\u094d\\u0932\\u092d \\u0909\\u092a-\\u0915\\u094d\\u0932\\u0938\\u094d\\u091f\\u0930\\u094b\\u0902 (\\u092a\\u094d\\u0930\\u0924\\u094d\\u092f\\u0947\\u0915 0.5%) \\u0915\\u0947 \\u0930\\u0942\\u092a \\u092e\\u0947\\u0902 \\u0907\\u0902\\u091c\\u0947\\u0915\\u094d\\u091f \\u0915\\u093f\\u092f\\u093e \\u091c\\u093e\\u090f\\u0917\\u093e, \\u091c\\u093f\\u0928\\u092e\\u0947\\u0902 \\u0935\\u093f\\u0936\\u093f\\u0937\\u094d\\u091f \\u092e\\u0932\\u094d\\u091f\\u0940-\\u092b\\u0940\\u091a\\u0930 \\u0907\\u0902\\u091f\\u0930\\u0948\\u0915\\u094d\\u0936\\u0928 \\u0939\\u094b\\u0902\\u0917\\u0947\\u0964 \\u0907\\u0938\\u0938\\u0947 \\u090f\\u0915 \\u0928\\u093f\\u0930\\u094d\\u0935\\u093f\\u0935\\u093e\\u0926 \\u0917\\u094d\\u0930\\u093e\\u0909\\u0902\\u0921 \\u091f\\u094d\\u0930\\u0941\\u0925 (Ground Truth) \\u0938\\u094d\\u0925\\u093e\\u092a\\u093f\\u0924 \\u0939\\u094b\\u0917\\u093e\\u0964\\n2. **\\u0935\\u093e\\u0938\\u094d\\u0924\\u0935\\u093f\\u0915 \\u092e\\u093e\\u0928\\u0915 \\u0921\\u0947\\u091f\\u093e\\u0938\\u0947\\u091f\\u094d\\u0938 (Real-World Tabular Datasets):**\\n   - **Forest CoverType (Covtype):** \\u0935\\u093f\\u0930\\u0932 \\u0935\\u0928-\\u092a\\u094d\\u0930\\u0915\\u093e\\u0930 \\u0935\\u0930\\u094d\\u0917 (\\u091c\\u0948\\u0938\\u0947 \\u0935\\u0930\\u094d\\u0917 4 \\u0935 5, \\u091c\\u094b \\u0915\\u0941\\u0932 \\u0921\\u0947\\u091f\\u093e \\u0915\\u093e <2% \\u0939\\u0948\\u0902)\\u0964\\n   - **Adult Census Income:** \\u0935\\u093f\\u0930\\u0932 \\u091c\\u0928\\u0938\\u093e\\u0902\\u0916\\u094d\\u092f\\u093f\\u0915\\u0940\\u092f \\u0935 \\u0935\\u094d\\u092f\\u093e\\u0935\\u0938\\u093e\\u092f\\u093f\\u0915 \\u0935\\u093f\\u0936\\u0947\\u0937\\u0924\\u093e\\u0913\\u0902 \\u0915\\u0947 \\u0938\\u0902\\u092f\\u094b\\u091c\\u0928 \\u0935\\u093e\\u0932\\u0940 \\u0909\\u092a-\\u091c\\u0928\\u0938\\u0902\\u0916\\u094d\\u092f\\u093e\\u0964\\n   - **Credit Card Fraud Detection:** \\u0905\\u0924\\u094d\\u092f\\u0927\\u093f\\u0915 \\u0905\\u0938\\u0902\\u0924\\u0941\\u0932\\u093f\\u0924 \\u0935\\u093f\\u0930\\u0932 \\u0938\\u0915\\u093e\\u0930\\u093e\\u0924\\u094d\\u092e\\u0915 \\u0935\\u0930\\u094d\\u0917 (0.17% \\u0926\\u0941\\u0930\\u094d\\u0932\\u092d \\u0932\\u0947\\u0928\\u0926\\u0947\\u0928)\\u0964\\n\\n#### 2.2 \\u092a\\u094d\\u0930\\u093e\\u092f\\u094b\\u0917\\u093f\\u0915 \\u0928\\u093f\\u092f\\u0902\\u0924\\u094d\\u0930\\u0923 (Experimental Controls)\\n- **\\u0938\\u0915\\u093e\\u0930\\u093e\\u0924\\u094d\\u092e\\u0915 \\u0928\\u093f\\u092f\\u0902\\u0924\\u094d\\u0930\\u0923 (Positive Controls):** \\u0938\\u094d\\u092a\\u0937\\u094d\\u091f \\u0930\\u0942\\u092a \\u0938\\u0947 \\u092a\\u0930\\u093f\\u092d\\u093e\\u0937\\u093f\\u0924, \\u0915\\u092e \\u0918\\u0928\\u0924\\u094d\\u0935 \\u0935\\u093e\\u0932\\u0947 \\u0938\\u0941\\u0938\\u0902\\u0917\\u0924 \\u0915\\u094d\\u0932\\u0938\\u094d\\u091f\\u0930\\u094d\\u0938, \\u091c\\u093f\\u0928\\u094d\\u0939\\u0947\\u0902 \\u0921\\u093f\\u091f\\u0947\\u0915\\u094d\\u091f\\u0930 \\u0915\\u094b \\u0905\\u0935\\u0936\\u094d\\u092f \\u092a\\u0939\\u091a\\u093e\\u0928\\u0928\\u093e \\u091a\\u093e\\u0939\\u093f\\u090f\\u0964\\n- **\\u0928\\u0915\\u093e\\u0930\\u093e\\u0924\\u094d\\u092e\\u0915 \\u0928\\u093f\\u092f\\u0902\\u0924\\u094d\\u0930\\u0923 (Negative Controls):** \\u092e\\u0941\\u0916\\u094d\\u092f \\u0935\\u093f\\u0924\\u0930\\u0923 (in-distribution) \\u092e\\u0947\\u0902 \\u091c\\u094b\\u0921\\u093c\\u093e \\u0917\\u092f\\u093e \\u0917\\u0949\\u0938\\u093f\\u092f\\u0928/\\u092f\\u0942\\u0928\\u093f\\u092b\\u0949\\u0930\\u094d\\u092e \\u0930\\u0935\\u0964 \\u0921\\u093f\\u091f\\u0947\\u0915\\u094d\\u091f\\u0930 \\u0915\\u094b \\u092f\\u0939 \\u0938\\u0924\\u094d\\u092f\\u093e\\u092a\\u093f\\u0924 \\u0915\\u0930\\u0928\\u093e \\u0939\\u094b\\u0917\\u093e \\u0915\\u093f \\u0935\\u0939 \\u0936\\u094b\\u0930 \\u0915\\u094b \\u0926\\u0941\\u0930\\u094d\\u0932\\u092d \\u092a\\u0948\\u091f\\u0930\\u094d\\u0928 \\u0915\\u0947 \\u0930\\u0942\\u092a \\u092e\\u0947\\u0902 \\u0917\\u0932\\u0924 \\u0935\\u0930\\u094d\\u0917\\u0940\\u0915\\u0943\\u0924 (False Positive) \\u0928 \\u0915\\u0930\\u0947\\u0964\\n- **\\u0932\\u0947\\u092c\\u0932 \\u0928\\u0949\\u0907\\u091c\\u093c \\u0928\\u093f\\u092f\\u0902\\u0924\\u094d\\u0930\\u0923 (Label Noise Disentanglement Control):** \\u0917\\u0932\\u0924 \\u0932\\u0947\\u092c\\u0932 \\u0915\\u093f\\u090f \\u0917\\u090f \\u0938\\u0948\\u0902\\u092a\\u0932\\u094d\\u0938 (\\u091c\\u094b \\u0915\\u094d\\u0932\\u093e\\u0938\\u093f\\u092b\\u093e\\u092f\\u0930 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u0909\\u091a\\u094d\\u091a \\u0939\\u093e\\u0928\\u093f \\u0926\\u0947\\u0924\\u0947 \\u0939\\u0948\\u0902 \\u0915\\u093f\\u0902\\u0924\\u0941 \\u092b\\u0940\\u091a\\u0930 \\u0938\\u094d\\u092a\\u0947\\u0938 \\u092e\\u0947\\u0902 \\u0938\\u0918\\u0928 \\u0939\\u094b\\u0924\\u0947 \\u0939\\u0948\\u0902) \\u0915\\u094b \\u0926\\u0941\\u0930\\u094d\\u0932\\u092d \\u092b\\u0940\\u091a\\u0930 \\u092a\\u0948\\u091f\\u0930\\u094d\\u0928\\u094d\\u0938 \\u0938\\u0947 \\u0905\\u0932\\u0917 \\u0915\\u0930\\u0928\\u0947 \\u0915\\u093e \\u0928\\u093f\\u092f\\u0902\\u0924\\u094d\\u0930\\u0923\\u0964\\n\\n---\\n\\n### 3. \\u091a\\u0930\\u0923\\u092c\\u0926\\u094d\\u0927 \\u092a\\u094d\\u0930\\u093e\\u092f\\u094b\\u0917\\u093f\\u0915 \\u092a\\u093e\\u0907\\u092a\\u0932\\u093e\\u0907\\u0928 (Step-by-Step Docta Workflow)\\n\\n```\\n[\\u0915\\u091a\\u094d\\u091a\\u093e \\u091f\\u0948\\u092c\\u0941\\u0932\\u0930 \\u0921\\u0947\\u091f\\u093e]\\n        \\u2502\\n        \\u25bc\\n[\\u092a\\u094d\\u0930\\u0940\\u092a\\u094d\\u0930\\u094b\\u0938\\u0947\\u0938\\u093f\\u0902\\u0917: \\u0938\\u094d\\u0915\\u0947\\u0932\\u093f\\u0902\\u0917, \\u090f\\u0928\\u0915\\u094b\\u0921\\u093f\\u0902\\u0917, \\u0907\\u092e\\u094d\\u092a\\u094d\\u092f\\u0942\\u091f\\u0947\\u0936\\u0928]\\n        \\u2502\\n        \\u25bc\\n[\\u091f\\u0948\\u092c\\u0941\\u0932\\u0930 \\u092c\\u0948\\u0915\\u092c\\u094b\\u0928 \\u092e\\u0949\\u0921\\u0932\\u093f\\u0902\\u0917 & \\u0930\\u093f\\u092a\\u094d\\u0930\\u091c\\u0947\\u0902\\u091f\\u0947\\u0936\\u0928 \\u090f\\u0915\\u094d\\u0938\\u091f\\u094d\\u0930\\u0948\\u0915\\u094d\\u0936\\u0928 (LightGBM / TabNet)]\\n        \\u2502\\n        \\u25bc\\n[Docta Rare Pattern Detection Engine]\\n  \\u251c\\u2500 \\u092b\\u0940\\u091a\\u0930 \\u0938\\u094d\\u092a\\u0947\\u0938 / \\u0932\\u0947\\u091f\\u0947\\u0902\\u091f \\u0921\\u0947\\u0902\\u0938\\u093f\\u091f\\u0940 \\u0906\\u0915\\u0932\\u0928 (k-NN / Kernel Density)\\n  \\u251c\\u2500 \\u0906\\u0909\\u091f-\\u0911\\u092b-\\u092b\\u094b\\u0932\\u094d\\u0921 \\u092a\\u094d\\u0930\\u0947\\u0921\\u093f\\u0915\\u094d\\u091f\\u093f\\u0935 \\u0915\\u0902\\u0938\\u093f\\u0938\\u094d\\u091f\\u0947\\u0902\\u0938\\u0940 / \\u0905\\u0928\\u093f\\u0936\\u094d\\u091a\\u093f\\u0924\\u0924\\u093e \\u0938\\u094d\\u0915\\u094b\\u0930\\u093f\\u0902\\u0917\\n  \\u2514\\u2500 \\u0938\\u092c-\\u092a\\u0949\\u092a\\u0941\\u0932\\u0947\\u0936\\u0928 \\u0915\\u094d\\u0932\\u0938\\u094d\\u091f\\u0930\\u093f\\u0902\\u0917 \\u090f\\u0935\\u0902 \\u0930\\u0947\\u0938\\u093f\\u0921\\u094d\\u092f\\u0942\\u0905\\u0932 \\u090f\\u0928\\u093e\\u0932\\u093f\\u0938\\u093f\\u0938\\n        \\u2502\\n        \\u25bc\\n[Rarity Score \\u0905\\u0938\\u093e\\u0907\\u0928\\u092e\\u0947\\u0902\\u091f & \\u0930\\u0948\\u0902\\u0915\\u093f\\u0902\\u0917 S_rare(x)]\\n        \\u2502\\n        \\u25bc\\n[\\u0924\\u0941\\u0932\\u0928\\u093e\\u0924\\u094d\\u092e\\u0915 \\u092e\\u0942\\u0932\\u094d\\u092f\\u093e\\u0902\\u0915\\u0928 (Baselines) \\u090f\\u0935\\u0902 \\u0907\\u0902\\u091f\\u0930\\u092a\\u094d\\u0930\\u093f\\u091f\\u0947\\u092c\\u093f\\u0932\\u093f\\u091f\\u0940 (SHAP)]\\n```\\n\\n#### \\u091a\\u0930\\u0923 1: \\u0921\\u0947\\u091f\\u093e \\u092a\\u094d\\u0930\\u0940\\u092a\\u094d\\u0930\\u094b\\u0938\\u0947\\u0938\\u093f\\u0902\\u0917 (Data Preprocessing)\\n- \\u0938\\u0902\\u0916\\u094d\\u092f\\u093e\\u0924\\u094d\\u092e\\u0915 \\u092b\\u0940\\u091a\\u0930\\u094d\\u0938: RobustScaler \\u092f\\u093e QuantileTransformer \\u0926\\u094d\\u0935\\u093e\\u0930\\u093e \\u092e\\u093e\\u0928\\u0915\\u0940\\u0915\\u0930\\u0923 (\\u0924\\u093e\\u0915\\u093f \\u0906\\u0909\\u091f\\u0932\\u093e\\u092f\\u0930\\u094d\\u0938 \\u0938\\u094d\\u0915\\u0947\\u0932\\u093f\\u0902\\u0917 \\u0915\\u094b \\u0935\\u093f\\u0915\\u0943\\u0924 \\u0928 \\u0915\\u0930\\u0947\\u0902)\\u0964\\n- \\u0936\\u094d\\u0930\\u0947\\u0923\\u0940\\u092c\\u0926\\u094d\\u0927 \\u092b\\u0940\\u091a\\u0930\\u094d\\u0938: \\u0939\\u093e\\u0908-\\u0915\\u093e\\u0930\\u094d\\u0921\\u093f\\u0928\\u0948\\u0932\\u093f\\u091f\\u0940 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u091f\\u093e\\u0930\\u0917\\u0947\\u091f \\u090f\\u0928\\u0915\\u094b\\u0921\\u093f\\u0902\\u0917 \\u0905\\u0925\\u0935\\u093e \\u0935\\u0928-\\u0939\\u0949\\u091f \\u090f\\u0928\\u0915\\u094b\\u0921\\u093f\\u0902\\u0917\\u0964\\n- \\u0932\\u0941\\u092a\\u094d\\u0924 \\u092e\\u093e\\u0928 (Missing Values): KNN-\\u0907\\u092e\\u094d\\u092a\\u094d\\u092f\\u0942\\u091f\\u0930 \\u092f\\u093e \\u092e\\u0940\\u0921\\u093f\\u092f\\u0928/\\u092e\\u094b\\u0921 \\u092a\\u094d\\u0930\\u0924\\u093f\\u0938\\u094d\\u0925\\u093e\\u092a\\u0928\\u0964\\n\\n#### \\u091a\\u0930\\u0923 2: \\u092b\\u0940\\u091a\\u0930 \\u0930\\u093f\\u092a\\u094d\\u0930\\u091c\\u0947\\u0902\\u091f\\u0947\\u0936\\u0928 \\u090f\\u0935\\u0902 \\u092c\\u0948\\u0915\\u092c\\u094b\\u0928 \\u092e\\u0949\\u0921\\u0932\\u093f\\u0902\\u0917 (Representation Learning)\\n- \\u090f\\u0915 \\u091f\\u094d\\u0930\\u0940-\\u090f\\u0902\\u0938\\u0947\\u0902\\u092c\\u0932 (LightGBM / CatBoost) \\u092f\\u093e \\u091f\\u0948\\u092c\\u0941\\u0932\\u0930 \\u0928\\u094d\\u092f\\u0942\\u0930\\u0932 \\u0928\\u0947\\u091f\\u0935\\u0930\\u094d\\u0915 (TabNet/MLP) \\u0915\\u093e \\u0909\\u092a\\u092f\\u094b\\u0917 \\u0915\\u0930\\u0915\\u0947 5-\\u092b\\u094b\\u0932\\u094d\\u0921 \\u0915\\u094d\\u0930\\u0949\\u0938-\\u0935\\u0948\\u0932\\u093f\\u0921\\u0947\\u0936\\u0928 \\u0915\\u0947 \\u0924\\u0939\\u0924:\\n  - \\u0932\\u0947\\u091f\\u0947\\u0902\\u091f \\u092b\\u0940\\u091a\\u0930 \\u090f\\u092e\\u094d\\u092c\\u0947\\u0921\\u093f\\u0902\\u0917\\u094d\\u0938 (penultimate layer embeddings) \\u092a\\u094d\\u0930\\u093e\\u092a\\u094d\\u0924 \\u0915\\u0930\\u0928\\u093e\\u0964\\n  - \\u0906\\u0909\\u091f-\\u0911\\u092b-\\u092b\\u094b\\u0932\\u094d\\u0921 (OOF) \\u092a\\u094d\\u0930\\u0947\\u0921\\u093f\\u0915\\u094d\\u0936\\u0928 \\u092a\\u094d\\u0930\\u094b\\u092c\\u0947\\u092c\\u093f\\u0932\\u093f\\u091f\\u0940 \\u0921\\u093f\\u0938\\u094d\\u091f\\u094d\\u0930\\u0940\\u092c\\u094d\\u092f\\u0942\\u0936\\u0928 \\u0928\\u093f\\u0915\\u093e\\u0932\\u0928\\u093e\\u0964\\n\\n#### \\u091a\\u0930\\u0923 3: Docta \\u0926\\u094d\\u0935\\u093e\\u0930\\u093e \\u0926\\u0941\\u0930\\u094d\\u0932\\u092d \\u092a\\u0948\\u091f\\u0930\\u094d\\u0928 \\u0938\\u094d\\u0915\\u094b\\u0930\\u093f\\u0902\\u0917 (Docta Scoring Mechanism)\\nDocta \\u0915\\u0947 \\u0905\\u0902\\u0924\\u0930\\u094d\\u0917\\u0924 \\u0928\\u093f\\u092e\\u094d\\u0928\\u0932\\u093f\\u0916\\u093f\\u0924 \\u0926\\u094b\\u0939\\u0930\\u0947 \\u0924\\u0902\\u0924\\u094d\\u0930 (dual-mechanism) \\u0938\\u0947 \\u092a\\u094d\\u0930\\u0924\\u094d\\u092f\\u0947\\u0915 \\u0938\\u0948\\u0902\\u092a\\u0932 $x_i$ \\u0915\\u0947 \\u0932\\u093f\\u090f \\u090f\\u0915 \\u0926\\u0941\\u0930\\u094d\\u0932\\u092d\\u0924\\u093e \\u0938\\u094d\\u0915\\u094b\\u0930 ($S_{\\\\text{rare}}(x_i)$) \\u0924\\u0948\\u092f\\u093e\\u0930 \\u0915\\u093f\\u092f\\u093e \\u091c\\u093e\\u0924\\u093e \\u0939\\u0948:\\n1. **\\u0932\\u094b\\u0915\\u0932 \\u0921\\u0947\\u0902\\u0938\\u093f\\u091f\\u0940 \\u0938\\u094d\\u0915\\u094b\\u0930 ($S_{\\\\text{density}}$):**\\n   \\u0930\\u093f\\u092a\\u094d\\u0930\\u091c\\u0947\\u0902\\u091f\\u0947\\u0936\\u0928 \\u0938\\u094d\\u092a\\u0947\\u0938 \\u092e\\u0947\\u0902 $k$-\\u0928\\u093f\\u0915\\u091f\\u0924\\u092e \\u092a\\u0921\\u093c\\u094b\\u0938\\u093f\\u092f\\u094b\\u0902 ($k$-NN, \\u091c\\u0939\\u093e\\u0901 $k=15$) \\u0915\\u0940 \\u0914\\u0938\\u0924 \\u0926\\u0942\\u0930\\u0940:\\n   $$S_{\\\\text{density}}(x_i) = \\\\frac{1}{k} \\\\sum_{j \\\\in \\\\mathcal{N}_k(x_i)} \\\\| \\\\phi(x_i) - \\\\phi(x_j) \\\\|_2$$\\n2. **\\u092a\\u094d\\u0930\\u0947\\u0921\\u093f\\u0915\\u094d\\u091f\\u093f\\u0935 \\u0915\\u0902\\u0938\\u093f\\u0938\\u094d\\u091f\\u0947\\u0902\\u0938\\u0940/\\u092e\\u093e\\u0930\\u094d\\u091c\\u093f\\u0928 \\u0938\\u094d\\u0915\\u094b\\u0930 ($S_{\\\\text{margin}}$):**\\n   \\u091f\\u0948\\u092c\\u0941\\u0932\\u0930 \\u092e\\u0949\\u0921\\u0932 \\u0926\\u094d\\u0935\\u093e\\u0930\\u093e \\u0905\\u0928\\u0941\\u092e\\u093e\\u0928\\u093f\\u0924 \\u0915\\u094d\\u0932\\u093e\\u0938 \\u092a\\u094d\\u0930\\u094b\\u092c\\u0947\\u092c\\u093f\\u0932\\u093f\\u091f\\u0940 \\u0915\\u093e \\u092e\\u093e\\u0930\\u094d\\u091c\\u093f\\u0928 \\u0914\\u0930 \\u090f\\u0928\\u094d\\u091f\\u094d\\u0930\\u093e\\u092a\\u0940, \\u091c\\u094b \\u092f\\u0939 \\u092e\\u093e\\u092a\\u0924\\u093e \\u0939\\u0948 \\u0915\\u093f \\u0915\\u094d\\u092f\\u093e \\u0921\\u0947\\u091f\\u093e \\u092c\\u093f\\u0902\\u0926\\u0941 \\u0915\\u093f\\u0938\\u0940 \\u0905\\u0938\\u094d\\u092a\\u0937\\u094d\\u091f \\u092f\\u093e \\u0935\\u093f\\u0930\\u0932 \\u0928\\u093f\\u0930\\u094d\\u0923\\u092f \\u0938\\u0940\\u092e\\u093e (decision boundary) \\u092a\\u0930 \\u0938\\u094d\\u0925\\u093f\\u0924 \\u0939\\u0948\\u0964\\n3. **\\u0938\\u0902\\u092f\\u0941\\u0915\\u094d\\u0924 \\u0926\\u0941\\u0930\\u094d\\u0932\\u092d\\u0924\\u093e \\u0938\\u094d\\u0915\\u094b\\u0930:**\\n   $$S_{\\\\text{rare}}(x_i) = \\\\alpha \\\\cdot \\\\text{Rank}(S_{\\\\text{density}}(x_i)) + (1 - \\\\alpha) \\\\cdot \\\\text{Rank}(S_{\\\\text{margin}}(x_i))$$\\n   (\\u091c\\u0939\\u093e\\u0901 $\\\\alpha \\\\in [0, 1]$ \\u090f\\u0915 \\u091f\\u094d\\u092f\\u0942\\u0928 \\u0915\\u0930\\u0928\\u0947 \\u092f\\u094b\\u0917\\u094d\\u092f \\u0935\\u0947\\u091f\\u093f\\u0902\\u0917 \\u092a\\u0948\\u0930\\u093e\\u092e\\u0940\\u091f\\u0930 \\u0939\\u0948, \\u0921\\u093f\\u092b\\u093c\\u0949\\u0932\\u094d\\u091f $\\\\alpha=0.7$)\\u0964\\n\\n#### \\u091a\\u0930\\u0923 4: \\u0925\\u094d\\u0930\\u0947\\u0936\\u094b\\u0932\\u094d\\u0921\\u093f\\u0902\\u0917 \\u090f\\u0935\\u0902 \\u0935\\u0930\\u094d\\u0917\\u0940\\u0915\\u0930\\u0923\\n- \\u0938\\u0948\\u0902\\u092a\\u0932\\u094d\\u0938 \\u0915\\u094b \\u0909\\u0928\\u0915\\u0947 $S_{\\\\text{rare}}$ \\u0938\\u094d\\u0915\\u094b\\u0930 \\u0915\\u0947 \\u0905\\u0935\\u0930\\u094b\\u0939\\u0940 \\u0915\\u094d\\u0930\\u092e \\u092e\\u0947\\u0902 \\u0930\\u0948\\u0902\\u0915 \\u0915\\u093f\\u092f\\u093e \\u091c\\u093e\\u0924\\u093e \\u0939\\u0948\\u0964\\n- \\u091f\\u0949\\u092a-$K\\\\%$ (\\u0909\\u0926\\u093e. \\u0936\\u0940\\u0930\\u094d\\u0937 1% \\u0938\\u0947 5%) \\u092c\\u093f\\u0902\\u0926\\u0941\\u0913\\u0902 \\u0915\\u094b \\u0938\\u0902\\u092d\\u093e\\u0935\\u093f\\u0924 'Rare Patterns' \\u0915\\u0947 \\u0930\\u0942\\u092a \\u092e\\u0947\\u0902 \\u092b\\u093c\\u094d\\u0932\\u0948\\u0917 \\u0915\\u093f\\u092f\\u093e \\u091c\\u093e\\u0924\\u093e \\u0939\\u0948\\u0964\\n\\n---\\n\\n### 4. \\u0924\\u0941\\u0932\\u0928\\u093e\\u0924\\u094d\\u092e\\u0915 \\u092c\\u0947\\u0938\\u0932\\u093e\\u0907\\u0928 \\u092e\\u0949\\u0921\\u0932\\u094d\\u0938 (Comparative Baselines)\\n\\nDocta \\u0915\\u0940 \\u092a\\u094d\\u0930\\u092d\\u093e\\u0935\\u0936\\u0940\\u0932\\u0924\\u093e \\u0915\\u093e \\u0928\\u093f\\u0937\\u094d\\u092a\\u0915\\u094d\\u0937 \\u092e\\u0942\\u0932\\u094d\\u092f\\u093e\\u0902\\u0915\\u0928 \\u0915\\u0930\\u0928\\u0947 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u0928\\u093f\\u092e\\u094d\\u0928\\u0932\\u093f\\u0916\\u093f\\u0924 \\u0938\\u094d\\u0925\\u093e\\u092a\\u093f\\u0924 \\u090f\\u0932\\u094d\\u0917\\u094b\\u0930\\u093f\\u0926\\u092e \\u0915\\u0947 \\u0938\\u093e\\u0925 \\u0924\\u0941\\u0932\\u0928\\u093e \\u0915\\u0940 \\u091c\\u093e\\u090f\\u0917\\u0940:\\n1. **Isolation Forest (iForest):** \\u0930\\u0948\\u0902\\u0921\\u092e \\u092a\\u093e\\u0930\\u094d\\u091f\\u0940\\u0936\\u0928\\u093f\\u0902\\u0917 \\u092a\\u0930 \\u0906\\u0927\\u093e\\u0930\\u093f\\u0924 \\u092e\\u093e\\u0928\\u0915 \\u091f\\u094d\\u0930\\u0940 \\u0906\\u0907\\u0938\\u094b\\u0932\\u0947\\u0936\\u0928 \\u0935\\u093f\\u0927\\u093f\\u0964\\n2. **Local Outlier Factor (LOF):** \\u0938\\u094d\\u0925\\u093e\\u0928\\u0940\\u092f \\u0918\\u0928\\u0924\\u094d\\u0935 \\u0935\\u093f\\u091a\\u0932\\u0928 \\u092a\\u0930 \\u0906\\u0927\\u093e\\u0930\\u093f\\u0924 \\u0915\\u094d\\u0932\\u093e\\u0938\\u093f\\u0915 \\u0935\\u093f\\u0927\\u093f\\u0964\\n3. **One-Class SVM (OC-SVM):** RBF \\u0915\\u0930\\u094d\\u0928\\u0932 \\u0915\\u0947 \\u0938\\u093e\\u0925 \\u0917\\u0948\\u0930-\\u0930\\u0948\\u0916\\u093f\\u0915 \\u0938\\u092a\\u094b\\u0930\\u094d\\u091f \\u0935\\u0947\\u0915\\u094d\\u091f\\u0930 \\u0921\\u0947\\u0902\\u0938\\u093f\\u091f\\u0940 \\u090f\\u0938\\u094d\\u091f\\u0940\\u092e\\u0947\\u091f\\u0930\\u0964\\n4. **Deep Tabular Autoencoder (AE):** \\u0930\\u0940\\u0915\\u0902\\u0938\\u094d\\u091f\\u094d\\u0930\\u0915\\u094d\\u0936\\u0928 \\u0932\\u0949\\u0938 (reconstruction error) \\u0915\\u0947 \\u0906\\u0927\\u093e\\u0930 \\u092a\\u0930 \\u0926\\u0941\\u0930\\u094d\\u0932\\u092d\\u0924\\u093e \\u0915\\u093e \\u092e\\u093e\\u092a\\u0928\\u0964\\n\\n\\u0938\\u092d\\u0940 \\u092c\\u0947\\u0938\\u0932\\u093f\\u0928\\u094b\\u0902 \\u0915\\u094b \\u0938\\u092e\\u093e\\u0928 \\u092a\\u094d\\u0930\\u0940\\u092a\\u094d\\u0930\\u094b\\u0938\\u0947\\u0938\\u